-- Simulated Policy Administration System (separate database: src_policy_admin)
DROP TABLE IF EXISTS premium_payments, policies, products;
CREATE TABLE products (
    product_code VARCHAR(20) PRIMARY KEY,
    product_name VARCHAR(100) NOT NULL,
    line_of_business VARCHAR(30) NOT NULL,
    base_annual_premium NUMERIC(12,2) NOT NULL);
CREATE TABLE policies (
    policy_number VARCHAR(20) PRIMARY KEY,
    customer_id VARCHAR(10) NOT NULL,          -- lives in CRM, no FK possible across systems
    product_code VARCHAR(20) NOT NULL REFERENCES products(product_code),
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    status VARCHAR(15) NOT NULL,
    annual_premium NUMERIC(12,2) NOT NULL,
    payment_frequency VARCHAR(15) NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE premium_payments (
    payment_id SERIAL PRIMARY KEY,
    policy_number VARCHAR(20) NOT NULL REFERENCES policies(policy_number),
    payment_date DATE NOT NULL,
    amount NUMERIC(12,2) NOT NULL,
    payment_method VARCHAR(20) NOT NULL);
